const { chromium } = require('playwright');

const TARGET_URL = 'file:///Users/jobinlawrance/Project/raven/.worktrees/raven-icon-font/ravenlogoassets/preview.html';

(async () => {
  const browser = await chromium.launch({ headless: false });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  const page = await ctx.newPage();
  const errs = [];
  page.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push(e.message));

  await page.goto(TARGET_URL, { waitUntil: 'load' });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(300);

  await page.screenshot({ path: '/tmp/raven-font-preview2.png', fullPage: true });
  const loaded = await page.evaluate(() => document.fonts.check('48px ravenicons'));
  console.log('fonts.check =>', loaded, '| errors:', errs.length ? errs : 'none');
  await browser.close();
})();

